import random
import string
from typing import List

# Generate valid Luau source code (text) that parses and exercises different constructs
# This buffer will be consumed by stubs via FUZZ_PARAM_STR as Luau source.
# We keep size <= 4096 bytes and ensure syntactic validity.

IDENT_START = string.ascii_letters + "_"
IDENT_CHARS = IDENT_START + string.digits


def _ident(r: random.Random, min_len=1, max_len=10) -> str:
    n = r.randint(min_len, max_len)
    s = r.choice(IDENT_START) + ''.join(r.choice(IDENT_CHARS) for _ in range(n - 1))
    # avoid reserved words occasionally
    if s in {"and","break","do","else","elseif","end","false","for","function","if","in","local","nil","not","or","repeat","return","then","true","until","while","type","typeof"}:
        s = s + "_x"
    return s


def _number_literal(r: random.Random) -> str:
    kinds = [
        lambda: str(r.randint(-1000, 1000)),
        lambda: f"{r.uniform(-1000,1000):.6f}",
        lambda: str(r.choice([0, 1, -1, 2**31-1, -2**31+1])),
    ]
    return r.choice(kinds)()


def _string_literal(r: random.Random) -> str:
    # generate safe quoted string with escapes
    length = r.randint(0, 16)
    chars = []
    for _ in range(length):
        ch = r.choice(string.ascii_letters + string.digits + " _-:/.,")
        chars.append(ch)
    s = ''.join(chars)
    # sometimes include escapes
    if r.random() < 0.3:
        s = s.replace("\\", "\\\\").replace("\"", "\\\"").replace("\n", "\\n")
    quote = r.choice(['"', "'"])
    if quote == '"':
        s = s.replace('"', '\\"')
    else:
        s = s.replace("'", "\\'")
    return f"{quote}{s}{quote}"


def _vector_ctor(r: random.Random) -> str:
    # standard vector ctor is vector.create(x,y,z)
    comps = [f"{r.uniform(-10,10):.3f}" for _ in range(3)]
    return f"vector.create({', '.join(comps)})"


def _expr(r: random.Random, depth=0) -> str:
    if depth > 3:
        return r.choice([_number_literal(r), _string_literal(r), _ident(r), _vector_ctor(r)])
    choices = []
    choices += [lambda: _number_literal(r), lambda: _string_literal(r), lambda: _ident(r), lambda: _vector_ctor(r)]
    choices += [
        lambda: f"({_expr(r, depth+1)})",
        lambda: f"{_expr(r, depth+1)} + {_expr(r, depth+1)}",
        lambda: f"{_expr(r, depth+1)} .. {_expr(r, depth+1)}",
        lambda: f"not {_expr(r, depth+1)}",
        lambda: f"-{_expr(r, depth+1)}",
        lambda: _table_expr(r, depth+1),
        lambda: f"{_ident(r)}({_args(r, depth+1)})",
        lambda: f"{_string_literal(r)}",
    ]
    return r.choice(choices)()


def _args(r: random.Random, depth=0) -> str:
    n = r.randint(0, 3)
    return ', '.join(_expr(r, depth+1) for _ in range(n))


def _table_expr(r: random.Random, depth=0) -> str:
    items: List[str] = []
    # mix of list and record fields
    for _ in range(r.randint(0, 4)):
        if r.random() < 0.5:
            items.append(_expr(r, depth+1))
        else:
            if r.random() < 0.5:
                # name key
                items.append(f"{_ident(r)} = {_expr(r, depth+1)}")
            else:
                # general key
                items.append(f"[{_expr(r, depth+1)}] = {_expr(r, depth+1)}")
    return "{" + ", ".join(items) + "}"


def _local_decl(r: random.Random) -> str:
    if r.random() < 0.4:
        # typed declaration syntax when allowed: local x: number = 5 (kept simple as plain)
        name = _ident(r)
        return f"local {name} = {_expr(r)}"
    # multiple assignment
    names = [_ident(r) for _ in range(r.randint(1, 3))]
    vals = [_expr(r) for _ in range(len(names))]
    return f"local {', '.join(names)} = {', '.join(vals)}"


def _function_def(r: random.Random, is_local=True, with_body=True) -> str:
    name = _ident(r)
    params = ', '.join(_ident(r) for _ in range(r.randint(0, 3)))
    head = f"local function {name}({params})" if is_local else f"function {name}({params})"
    body_lines = []
    # some simple body
    for _ in range(r.randint(0, 3)):
        kind = r.random()
        if kind < 0.33:
            body_lines.append(f"  local { _ident(r) } = {_expr(r)}")
        elif kind < 0.66:
            body_lines.append(f"  {_ident(r)} = {_expr(r)}")
        else:
            body_lines.append(f"  {_call_stmt(r)}")
    # return
    if r.random() < 0.7:
        retc = r.randint(0, 2)
        if retc == 0:
            body_lines.append("  return")
        else:
            body_lines.append("  return " + ', '.join(_expr(r) for _ in range(retc)))
    tail = "end"
    return "\n".join([head] + body_lines + [tail])


def _if_stmt(r: random.Random) -> str:
    cond = _expr(r)
    then_lines = ["  " + _simple_stmt(r) for _ in range(r.randint(0, 2))]
    else_lines = ["  " + _simple_stmt(r) for _ in range(r.randint(0, 2))]
    out = [f"if {cond} then"] + then_lines
    if r.random() < 0.7:
        out += ["else"] + else_lines
    out += ["end"]
    return "\n".join(out)


def _while_stmt(r: random.Random) -> str:
    cond = _expr(r)
    body = ["  " + _simple_stmt(r) for _ in range(r.randint(0, 3))]
    return "\n".join([f"while {cond} do"] + body + ["end"])


def _for_stmt(r: random.Random) -> str:
    v = _ident(r)
    a = _number_literal(r)
    b = _number_literal(r)
    if r.random() < 0.5:
        step = ", " + _number_literal(r)
    else:
        step = ""
    body = ["  " + _simple_stmt(r) for _ in range(r.randint(0, 2))]
    return "\n".join([f"for {v} = {a}, {b}{step} do"] + body + ["end"])


def _generic_for_stmt(r: random.Random) -> str:
    vars_ = ', '.join(_ident(r) for _ in range(r.randint(1, 2)))
    vals = ', '.join(["pairs({1,2,3})" if r.random()<0.5 else "ipairs({1,2,3})"])  # simple iterator
    body = ["  " + _simple_stmt(r) for _ in range(r.randint(0, 2))]
    return "\n".join([f"for {vars_} in {vals} do"] + body + ["end"])


def _assign_stmt(r: random.Random) -> str:
    lefts = [_ident(r) for _ in range(r.randint(1, 2))]
    rights = [_expr(r) for _ in range(len(lefts))]
    return f"{', '.join(lefts)} = {', '.join(rights)}"


def _call_stmt(r: random.Random) -> str:
    return f"{_ident(r)}({_args(r)})"


def _simple_stmt(r: random.Random) -> str:
    return r.choice([
        _assign_stmt,
        _call_stmt,
        lambda rr=r: f"local {_ident(rr)} = {_expr(rr)}",
    ])(r)


def _return_stmt(r: random.Random) -> str:
    if r.random() < 0.5:
        return "return"
    n = r.randint(1, 3)
    return "return " + ", ".join(_expr(r) for _ in range(n))


def _chunk(r: random.Random, max_bytes: int) -> str:
    parts: List[str] = []
    # optionally preload vector library usage to help BytecodeBuilder setDumpSource paths
    if r.random() < 0.4:
        parts.append("local v = vector.create(1,2,3)")
    # add a few locals/functions/flows
    for _ in range(r.randint(2, 6)):
        choice = r.random()
        if choice < 0.2:
            parts.append(_local_decl(r))
        elif choice < 0.4:
            parts.append(_function_def(r, is_local=True))
        elif choice < 0.55:
            parts.append(_if_stmt(r))
        elif choice < 0.7:
            parts.append(_while_stmt(r))
        elif choice < 0.85:
            parts.append(_for_stmt(r))
        else:
            parts.append(_generic_for_stmt(r))
    # end with a return to form a complete chunk
    parts.append(_return_stmt(r))
    code = "\n".join(parts)
    # Trim to size budget safely by cutting at line boundaries
    if len(code) > max_bytes:
        code = code[:max_bytes]
        # ensure final line ends correctly
        if not code.endswith("\n"):
            code += "\n"
    return code


def generate(seed: int) -> bytes:
    r = random.Random(seed)
    # Choose a size budget within 4KB cap but typically smaller for fast parsing/compilation pipelines
    max_bytes = r.randint(256, 2048)
    code = _chunk(r, max_bytes)
    # Ensure it's non-empty and syntactically plausible
    if not code.strip():
        code = "do end\n"
    # Return as bytes (UTF-8)
    data = code.encode('utf-8', errors='replace')
    # Guard final size
    return data[:4096]

import random
import string
from typing import List

# Target data type: C string (identifier-like)
# This generator crafts null-terminated UTF-8/ASCII names suitable for:
# - Luau::BytecodeBuilder::addUserdataType (expects const char* name)
# - Luau::BytecodeBuilder::useUserdataType (same)
# - Luau::AstExprTable::getRecord (record key string)
# - Luau::AstNameTable::{addStatic,get} (identifier-like names)
#
# Strategy:
# - Emit a single buffer that can be consumed by FUZZ_PARAM_STR/FUZZ_PARAM_FILENAME.
# - Populate the buffer with one or more NUL-terminated strings (C strings) concatenated,
#   so multiple FUZZ_PARAM_STR calls can each read a valid string.
# - Include a variety of identifier styles to exercise different code paths:
#   * Simple ASCII identifiers
#   * Namespaced/dotted paths (for record-like lookups)
#   * Names with underscores, digits, mixed case
#   * Unicode identifier-like examples (valid UTF-8)
#   * Edge cases: empty -> replaced by minimal valid identifier "x"
# - Ensure total size <= 4096 bytes.
#
# Buffer layout:
#   [cstr1]\0[cstr2]\0...\0
# Consumers that read one string will get the first; subsequent calls will get following ones.

_MAX_BYTES = 4096

_SIMPLE_IDS = [
    "x", "y", "z", "t", "u", "v",
    "_", "__", "_x", "x_", "__name__",
    "UserData", "Vector4", "TypeName", "get", "set", "update",
    "foo", "bar", "baz", "qux", "main", "init",
]

# A few dotted keys useful for record-style access (AstExprTable::getRecord)
_DOTTED = [
    "config.value", "player.stats.health", "env.PATH", "meta.__index", "__tostring",
]

# Some unicode identifier-like samples (valid UTF-8)
_UNICODE = [
    "naïve",            # Latin-1 with diaeresis
    "café",             # Latin-1 with acute
    "лента",            # Cyrillic
    "变量",              # CJK
    "αβγ",              # Greek
    "🚀rocket",         # emoji + ascii
]

# Identifier character sets
_ID_START = string.ascii_letters + "_"
_ID_CONT = _ID_START + string.digits


def _rand_identifier(rng: random.Random, min_len=1, max_len=24) -> str:
    n = rng.randint(min_len, max_len)
    if n <= 0:
        return "x"
    s = rng.choice(_ID_START)
    if n > 1:
        s += "".join(rng.choice(_ID_CONT) for _ in range(n - 1))
    return s


def _rand_dotted(rng: random.Random) -> str:
    parts = [
        _rand_identifier(rng, 1, rng.randint(3, 10))
        for _ in range(rng.randint(2, 4))
    ]
    return ".".join(parts)


def _maybe_empty_minimal(rng: random.Random) -> str:
    # Occasionally return empty, but we will replace with minimal valid later.
    return "" if rng.random() < 0.2 else _rand_identifier(rng)


def _sanitize_empty(s: str) -> str:
    # For APIs expecting identifier-like names, empty is not very useful; map to "x".
    return s if s else "x"


def _pick_weighted(rng: random.Random) -> str:
    choice = rng.random()
    if choice < 0.25:
        return rng.choice(_SIMPLE_IDS)
    elif choice < 0.45:
        return _rand_identifier(rng, 1, 24)
    elif choice < 0.65:
        return _rand_dotted(rng)
    elif choice < 0.8:
        return rng.choice(_DOTTED)
    elif choice < 0.95:
        return rng.choice(_UNICODE)
    else:
        return _maybe_empty_minimal(rng)


def _build_strings(rng: random.Random) -> List[str]:
    # Generate a small set of varied, valid C strings
    count = rng.randint(3, 8)
    out: List[str] = []
    used = set()
    for _ in range(count):
        s = _pick_weighted(rng)
        s = _sanitize_empty(s)
        # Deduplicate to provide distinct inputs across multiple FUZZ_PARAM_STR usages
        for _retry in range(5):
            if s not in used:
                break
            s = _rand_identifier(rng)
        used.add(s)
        out.append(s)
    return out


def generate(seed: int) -> bytes:
    rng = random.Random(seed)

    strings = _build_strings(rng)

    # Ensure we include at least one plain identifier and one dotted key
    if not any("." in s for s in strings):
        strings.append(_rand_dotted(rng))
    if not any(s.isidentifier() or (s and (s[0].isalpha() or s[0] == "_")) for s in strings):
        strings.append(_rand_identifier(rng))

    # Encode as UTF-8 C-strings with NUL terminators, concatenated
    chunks: List[bytes] = []
    total = 0
    for s in strings:
        b = s.encode("utf-8", errors="strict") + b"\x00"
        if total + len(b) > _MAX_BYTES:
            break
        chunks.append(b)
        total += len(b)

    # Fallback to at least one minimal identifier if all trimmed
    if not chunks:
        chunks = [b"x\x00"]

    return b"".join(chunks)

import random
import string

# Generator for Luau expressions
# We focus on producing syntactically valid and diverse single expressions that
# exercise many parser paths: literals, tables, function literals, unary/binary ops,
# method/index calls, varargs, interpolated/quoted strings, generics on calls,
# type assertions, if-then-else expressions, and vectors/numbers.

MAX_BYTES = 1024

IDENT_START = string.ascii_letters + "_"
IDENT_BODY = IDENT_START + string.digits

BIN_OPS = [
    "+", "-", "*", "/", "//", "%", "^", "..",
    "~=", "==", "<", "<=", ">", ">=",
    "and", "or",
]
UNARY_OPS = ["not", "-", "#"]

# Some useful expression atoms
LITERALS = [
    "nil", "true", "false",
    "0", "1", "-1", "3.14159", "1e9", "0xFF", "0b1010",
]

RAW_STR_FRAGMENTS = [
    "hello", "Luau", "unicode_μ", "line\nfeed", "tab\tsep", "quote\"", "single'", "\\backslash",
]

# Helper: random identifier

def r_ident(r: random.Random, minlen=1, maxlen=10):
    n = r.randint(minlen, maxlen)
    s = r.choice(IDENT_START)
    s += "".join(r.choice(IDENT_BODY) for _ in range(n-1))
    return s

# Helper: quoted string literal (single or double)

def r_string(r: random.Random):
    if r.random() < 0.2:
        # long raw string [[...]] or [=[...]=]
        frag = r.choice(RAW_STR_FRAGMENTS)
        # choose equals count 0..2
        eq = "=" * r.randint(0, 2)
        return f"[${eq}[{frag}]${eq}]".replace("$", "")
    # quoted string
    quote = r.choice(['"', "'"])
    frag = r.choice(RAW_STR_FRAGMENTS)
    # escape the matching quote minimally
    frag = frag.replace(quote, "\\" + quote)
    return f"{quote}{frag}{quote}"

# Helper: table constructor

def r_table(r: random.Random, depth):
    items = []
    # choose between list items, record fields, and general key/value
    count = r.randint(0, 4)
    for _ in range(count):
        kind = r.choice(["list", "record", "general"]) if depth < 2 else r.choice(["list", "record"])  # reduce recursion
        if kind == "list":
            items.append(r_expr(r, depth+1))
        elif kind == "record":
            k = r_ident(r)
            v = r_expr(r, depth+1)
            items.append(f"{k} = {v}")
        else:
            kexpr = r_expr_atom(r, depth+1)
            vexpr = r_expr(r, depth+1)
            items.append(f"[{kexpr}] = {vexpr}")
    return "{" + (", ".join(items)) + "}"

# Helper: function literal expression

def r_function(r: random.Random, depth):
    # args (0..3), optional vararg
    argc = r.randint(0, 3)
    args = [r_ident(r) for _ in range(argc)]
    if r.random() < 0.3:
        args.append("...")
    # very small body as an expression statement: return <expr list>
    rets = ", ".join(r_expr(r, depth+1) for _ in range(r.randint(1, 2)))
    body = f"return {rets}"
    return f"function({', '.join(args)}) {body} end"

# Helper: call arguments (simple to keep single expression valid)

def r_callargs(r: random.Random, depth):
    # sometimes use single-string/table sugar
    mode = r.random()
    if mode < 0.2:
        return " " + r_string(r)
    if mode < 0.3:
        return " " + r_table(r, depth)
    # parenthesized argument list
    n = r.randint(0, 3)
    args = ", ".join(r_expr(r, depth+1) for _ in range(n))
    return f"({args})"

# Atoms that are terminal enough to control recursion

def r_expr_atom(r: random.Random, depth):
    choice = r.random()
    if choice < 0.15:
        return r_string(r)
    if choice < 0.30:
        return r.choice(LITERALS)
    if choice < 0.45:
        return r_table(r, depth)
    if choice < 0.60 and depth < 2:
        return r_function(r, depth)
    # identifier or dotted name
    name = r_ident(r)
    # maybe module-like prefix a.b.c
    if r.random() < 0.25:
        name = ".".join(r_ident(r) for _ in range(r.randint(2, 3)))
    return name

# Build more complex expressions

def r_expr_suffixes(r: random.Random, base: str, depth):
    # apply a random chain of indexing, method calls, and field access
    steps = r.randint(0, 3)
    s = base
    for _ in range(steps):
        t = r.random()
        if t < 0.33:
            # index by name or expr
            if r.random() < 0.6:
                s += "." + r_ident(r)
            else:
                s += f"[" + r_expr(r, depth+1) + "]"
        elif t < 0.66:
            # method call or plain call
            if r.random() < 0.5:
                s += ":" + r_ident(r) + r_callargs(r, depth)
            else:
                s += r_callargs(r, depth)
        else:
            # type assertion :: <Type> (simple named type or union)
            if r.random() < 0.5:
                s += f" :: {r_ident(r)}"
            else:
                s += f" :: {r_ident(r)} | {r_ident(r)}"
    return s

# Expression with unary/binary ops, if-then-else expr, concat etc.

def r_expr(r: random.Random, depth=0):
    # Control recursion depth
    if depth > 3:
        return r_expr_atom(r, depth)

    choice = r.random()
    if choice < 0.20:
        # unary op
        op = r.choice(UNARY_OPS)
        rhs = r_expr(r, depth+1)
        # Ensure spacing for not / length
        if op == "not":
            return f"not {rhs}"
        elif op == "#":
            return f"#{rhs}"
        else:
            return f"-{rhs}"
    if choice < 0.45:
        # binary op chain of 2-3 terms
        parts = [r_expr(r, depth+1) for _ in range(r.randint(2, 3))]
        ops = [r.choice(BIN_OPS) for _ in range(len(parts)-1)]
        expr = parts[0]
        for o, p in zip(ops, parts[1:]):
            # ensure spacing around word ops
            if o in ("and", "or"):
                expr = f"({expr} {o} {p})"
            else:
                expr = f"({expr} {o} {p})"
        return expr
    if choice < 0.60 and depth < 3:
        # if-then-else expression
        c = r_expr(r, depth+1)
        t = r_expr(r, depth+1)
        e = r_expr(r, depth+1)
        return f"if {c} then {t} else {e}"
    if choice < 0.75:
        # parenthesized group
        return f"({r_expr(r, depth+1)})"
    if choice < 0.90:
        # interpolated string simple: `a{expr}b`
        # Keep it simple to stay under parser constraints
        left = r.choice(["a", "x", "_", "num"])  # simple safe chunk
        mid = r_expr(r, depth+1)
        right = r.choice(["b", "y", "_end"]) 
        # Escaping braces handled by parser; we produce simple single-interp
        return f"`{left}{{{mid}}}{right}`"

    # base atom with suffix chain
    base = r_expr_atom(r, depth)
    return r_expr_suffixes(r, base, depth)

# Top-level expression factory combining different high-level patterns

def generate_expression(r: random.Random):
    pattern = r.random()
    if pattern < 0.15:
        # simple literal or string
        return r.choice(LITERALS + [r_string(r)])
    if pattern < 0.30:
        # table constructor
        return r_table(r, 0)
    if pattern < 0.45:
        # function literal (expression)
        return r_function(r, 0)
    if pattern < 0.65:
        # call chain on identifier
        base = r_ident(r)
        expr = r_expr_suffixes(r, base, 0)
        return expr
    # general recursive expression
    return r_expr(r, 0)


def clamp_bytes(b: bytes) -> bytes:
    if len(b) > MAX_BYTES:
        return b[:MAX_BYTES]
    return b


def generate(seed: int) -> bytes:
    r = random.Random(seed)

    # Build a pool of candidate expressions and pick one to keep variability
    candidates = []
    count = r.randint(1, 4)
    for _ in range(count):
        expr = generate_expression(r)
        candidates.append(expr)

    # Prefer longer but valid-looking candidate to exercise parser
    expr = max(candidates, key=len)

    # Very small chance to wrap with generic instantiation call pattern f<'T'>(args)
    if r.random() < 0.15:
        fname = r_ident(r)
        # create simple type arg list
        targs = ", ".join(r_ident(r) for _ in range(r.randint(1, 2)))
        args = r_callargs(r, 0)
        expr = f"{fname}< {targs} >{args}"

    # Ensure non-empty and ASCII-friendly output; Luau supports UTF-8 but keep simple
    expr = expr.strip()
    if not expr:
        expr = "0"

    data = expr.encode("utf-8", errors="ignore")
    return clamp_bytes(data)

import random
import string
from typing import List

# Generator for Luau type annotation fragments suitable for Luau::Parser::parseType
# It tries to cover a broad subset of Luau type syntax: primitives, unions, intersections,
# optionals, function types (with generics, attributes, varargs, named params, return packs),
# table types with properties and indexers (read/write), typeof, singleton types, and grouping.

PRIMS = [
    "nil", "boolean", "number", "string", "thread", "userdata", "vector", "buffer", "any",
]

ATTRIBUTES = ["checked", "native", "deprecated"]
TABLE_ACCESS = ["read", "write", "readwrite"]

IDENT_CHARS = string.ascii_letters + string.digits + "_"


def rchoice(rng: random.Random, seq: List[str]):
    return rng.choice(seq)


def ident(rng: random.Random, minlen=1, maxlen=8):
    L = rng.randint(minlen, maxlen)
    # Ensure first is alpha/_ to be a valid identifier
    first = rng.choice(string.ascii_letters + "_")
    rest = ''.join(rng.choice(IDENT_CHARS) for _ in range(L-1))
    return first + rest


def maybe(rng: random.Random, p: float) -> bool:
    return rng.random() < p


def ty_primitive(rng: random.Random) -> str:
    return rchoice(rng, PRIMS)


def ty_singleton(rng: random.Random) -> str:
    # 'true'|'false' or a quoted string literal singleton
    if maybe(rng, 0.5):
        return rchoice(rng, ["true", "false"])  # singleton bools
    # generate a short quoted string; keep simple escaping to avoid parser confusion
    s = ''.join(rng.choice(string.ascii_lowercase + string.digits) for _ in range(rng.randint(0, 6)))
    quote = rchoice(rng, ['"', "'"])
    return f"{quote}{s}{quote}"


def ty_name(rng: random.Random) -> str:
    # Possibly prefixed name like Module.Type<T>
    if maybe(rng, 0.3):
        prefix = ident(rng)
        name = ident(rng)
        full = f"{prefix}.{name}"
    else:
        full = ident(rng)
    # Optional type parameters
    if maybe(rng, 0.35):
        params = [gen_type(rng, depth=1) for _ in range(rng.randint(1, 3))]
        full += "<" + ", ".join(params) + ">"
    return full


def ty_optional(rng: random.Random, base: str) -> str:
    return f"{base}?"


def ty_union(rng: random.Random, depth: int) -> str:
    parts = [gen_type(rng, depth+1) for _ in range(rng.randint(2, 4))]
    return " | ".join(parts)


def ty_intersection(rng: random.Random, depth: int) -> str:
    parts = [gen_type(rng, depth+1) for _ in range(rng.randint(2, 3))]
    return " & ".join(parts)


def ty_table(rng: random.Random, depth: int) -> str:
    # Build a table type with a mix of named props and indexer
    props = []
    for _ in range(rng.randint(0, 4)):
        name = ident(rng)
        access = ""
        if maybe(rng, 0.3):
            acc = rchoice(rng, TABLE_ACCESS)
            access = f" {acc}"
        t = gen_type(rng, depth+1)
        props.append(f"{name}:{access} {t}")
    # Maybe an indexer
    indexer = ""
    if maybe(rng, 0.4):
        acc = rchoice(rng, TABLE_ACCESS)
        idxT = rchoice(rng, ["number", "string"]) if maybe(rng, 0.7) else gen_type(rng, depth+1)
        resT = gen_type(rng, depth+1)
        indexer = f"[{idxT}]: {acc} {resT}"
    body_items = ", ".join([*props, *([indexer] if indexer else [])])
    return "{" + body_items + "}"


def ty_typeof(rng: random.Random) -> str:
    # typeof(<expr>) where <expr> is simple identifier or table access; we keep it simple to be accepted by parser
    base = ident(rng)
    tail = ""
    if maybe(rng, 0.5):
        tail = "." + ident(rng)
    return f"typeof({base}{tail})"


def ty_pack(rng: random.Random, depth: int) -> str:
    # A type pack like (T1, T2, ...T3)
    items = [gen_type(rng, depth+1) for _ in range(rng.randint(1, 3))]
    if maybe(rng, 0.4):
        # variadic tail
        items.append("..." + gen_type(rng, depth+1))
    return "(" + ", ".join(items) + ")"


def ty_function(rng: random.Random, depth: int) -> str:
    # Optional attributes
    attr = ""
    attrs: List[str] = []
    if maybe(rng, 0.35):
        k = rng.randint(1, 2)
        attrs = rng.sample(ATTRIBUTES, k=k)
        # Optionally include a deprecated(reason) form
        args = []
        for a in attrs:
            if a == "deprecated" and maybe(rng, 0.5):
                # deprecated("use X")
                reason = ident(rng)
                args.append(f"{a}(\"use {reason}\")")
            else:
                args.append(a)
        attr = "<" + ", ".join(args) + ">"
    # Optional generics
    gen = ""
    if maybe(rng, 0.4):
        # Name or name = default
        gnames = []
        for _ in range(rng.randint(1, 2)):
            n = ident(rng)
            if maybe(rng, 0.4):
                gnames.append(f"{n} = {gen_type(rng, depth+1)}")
            else:
                gnames.append(n)
        # Optional generic packs too
        if maybe(rng, 0.3):
            pn = ident(rng)
            if maybe(rng, 0.5):
                gnames.append(f"...{pn} = {gen_type(rng, depth+1)}")
            else:
                gnames.append("..." + pn)
        gen = "<" + ", ".join(gnames) + ">"
    # Parameters
    params = []
    named = maybe(rng, 0.5)
    for _ in range(rng.randint(0, 3)):
        t = gen_type(rng, depth+1)
        if named:
            pname = ident(rng)
            params.append(f"{pname}: {t}")
        else:
            params.append(t)
    # Optional vararg annotation
    if maybe(rng, 0.4):
        vtype = gen_type(rng, depth+1)
        params.append("..." + vtype)
    args = "(" + ", ".join(params) + ")"
    # Return types (possibly a pack)
    if maybe(rng, 0.4):
        # parenthesized return pack
        retty = ty_pack(rng, depth+1)
    else:
        rets = [gen_type(rng, depth+1) for _ in range(rng.randint(0, 2))]
        if len(rets) == 0:
            retty = "()"
        elif len(rets) == 1:
            retty = rets[0]
        else:
            retty = "(" + ", ".join(rets) + ")"
    return f"{attr}({gen}){args} -> {retty}"


def gen_type(rng: random.Random, depth: int = 0) -> str:
    # Limit recursion depth
    if depth > 3:
        choice = rng.randint(0, 4)
        if choice == 0:
            return ty_primitive(rng)
        if choice == 1:
            return ty_singleton(rng)
        if choice == 2:
            return ty_name(rng)
        if choice == 3:
            return ty_typeof(rng)
        return ty_table(rng, depth)

    alts = []
    alts.append(lambda: ty_primitive(rng))
    alts.append(lambda: ty_singleton(rng))
    alts.append(lambda: ty_name(rng))
    alts.append(lambda: ty_optional(rng, gen_type(rng, depth+1)))
    alts.append(lambda: ty_union(rng, depth))
    alts.append(lambda: ty_intersection(rng, depth))
    alts.append(lambda: ty_table(rng, depth))
    alts.append(lambda: ty_typeof(rng))
    alts.append(lambda: ty_function(rng, depth))
    alts.append(lambda: "(" + gen_type(rng, depth+1) + ")")
    # Slightly bias towards simpler primitives/names to keep strings valid often
    weights = [3, 2, 3, 2, 2, 2, 2, 2, 2, 2]
    idx = rng.choices(range(len(alts)), weights=weights, k=1)[0]
    return alts[idx]()


def assemble_fragment(rng: random.Random) -> str:
    t = gen_type(rng)
    # Sometimes wrap with comments and whitespace that parser can handle
    prefix = ""
    suffix = ""
    if maybe(rng, 0.3):
        prefix = "--!strict\n" if maybe(rng, 0.5) else ""
    if maybe(rng, 0.3):
        suffix = "\n"
    return prefix + t + suffix


def generate(seed: int) -> bytes:
    rng = random.Random(seed)
    # Produce a handful of interesting candidates and pick one to vary coverage
    candidates = []
    # Hand-crafted seeds for coverage of specific corners
    candidates.append("(number, string) -> (boolean, ...number)")
    candidates.append("{x: number, y: number, [string]: readwrite string}")
    candidates.append("(<checked> <T, ...U>)(a: T, ...U) -> (T)")
    candidates.append("nil | false | 'ok' | \"err\"")
    candidates.append("(vector) -> number")
    candidates.append("({a: number} & {b: string}) | typeof(foo.bar)")
    # Plus random ones
    for _ in range(6):
        candidates.append(assemble_fragment(rng))
    s = rchoice(rng, candidates)
    # Truncate to 1024 as the fuzzer does; also cap to 4096 per instruction
    s = s[:1024]
    return s.encode('utf-8', errors='strict')
